// Parse keyword JSON safely
const raw      = $input.item.json.output || '';

let formData;
try { formData = $('Parse Link Analysis').item.json; } catch(e) {}
try { if (!formData || !formData.topic) formData = $('No Link Skip').item.json; } catch(e) {}
if (!formData) formData = $input.item.json;

let kw = {};
try {
  const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  kw = JSON.parse(cleaned);
} catch(e) {
  const userKws = (formData.userKeywords || '').split(',').map(k => k.trim()).filter(Boolean);
  kw = {
    primaryKeyword:    userKws[0] || formData.topic,
    secondaryKeywords: userKws.length > 1 ? userKws.slice(1) : [formData.topic + ' guide', formData.topic + ' tips'],
    lsiKeywords:       [formData.topic + ' benefits', formData.topic + ' review'],
    metaTitle:         formData.topic.substring(0, 55),
    metaDescription:   'Complete guide about ' + formData.topic + '. Expert insights from ' + formData.brand,
    suggestedH2s:      ['Introduction', 'Key Benefits', 'How It Works', 'Expert Tips', 'Conclusion'],
    hookQuestion:      'Are you looking for the best way to approach ' + formData.topic + '?',
    tipBoxText:        'Start with one simple step and build from there.'
  };
}

return {
  json: {
    ...formData,
    primaryKeyword:    kw.primaryKeyword    || formData.topic,
    secondaryKeywords: (kw.secondaryKeywords || []).join(', '),
    lsiKeywords:       (kw.lsiKeywords       || []).join(', '),
    metaTitle:         kw.metaTitle         || formData.topic,
    metaDescription:   kw.metaDescription   || '',
    suggestedH2s:      (kw.suggestedH2s      || []).join(' | '),
    hookQuestion:      kw.hookQuestion       || '',
    tipBoxText:        kw.tipBoxText         || ''
  }
};

const d = $input.item.json;
// ✅ ADD THIS — Product Reference Link
const productRefLink =
  d.refLink ||
  d.productRefLink ||
  $input.first().json['Product Reference Link (Optional)'] ||
  $input.first().json.body?.['Product Reference Link (Optional)'] ||
  '';
const tableInstruction = d.needTable === 'Yes'
  ? 'MUST include at least one properly formatted markdown comparison table.'
  : 'Do NOT include any tables.';
const tldrInstruction = d.needTldr === 'Yes'
  ? 'MUST include a TL;DR section immediately after the meta description line, formatted as: TL;DR: [2-3 sentence summary]'
  : 'Do NOT include a TL;DR section.';
const faqInstruction = `CONCLUSION THEN FAQS RULE:
1. Write ## Conclusion BEFORE FAQs.
2. Write exactly ${d.faqCount} FAQs after conclusion.
FAQ CRITICAL RULES:
- At least 2 out of ${d.faqCount} FAQs MUST naturally mention the brand name "${d.brand}" in the answer.
  Example: "At ${d.brand}, we recommend..." or "${d.brand} offers..." or "Our team at ${d.brand} suggests..."
- Every FAQ answer MUST reflect the user's chosen writing style: ${d.styleName}
- FAQ answers MUST align with the target audience: ${d.targetOrigin || 'Global'} audience, ${d.targetGender || 'All'} gender, age group ${d.targetAge || 'All Ages'}
- Use the tone and vocabulary from the brand story context: "${d.shortBrandStory ? d.shortBrandStory.substring(0, 120) : 'the brand'}"
- FAQ style: ${d.faqStyle}
FAQ format:
Q1. Question here
Answer here (no blank line between Q and A)
Q2. Next question
Next answer`;
const refStyleSection = d.refStyleInjection && d.refStyleInjection.trim() !== ''
  ? `\n${d.refStyleInjection}\n`
  : '';
const audienceSection = `
TARGET AUDIENCE PROFILE — Write specifically for this audience:
- Target Origin/Location: ${d.targetOrigin || 'Global'}
- Target Gender: ${d.targetGender || 'All'}
- Target Age Group: ${d.targetAge || 'All Ages'}
- Product Category: ${d.productCategory || 'General'}
ADAPT the writing style, cultural references, examples, and product mentions to resonate specifically with this audience profile. If the origin is a specific country, use relevant local references, currency, and examples where appropriate.`;
const brandStorySection = d.shortBrandStory && d.shortBrandStory.trim() !== ''
  ? `
BRAND STORY CONTEXT — Use this to add authenticity and brand voice:
${d.shortBrandStory}
Weave the brand story naturally into the introduction or a dedicated brand section. Use it to build trust and emotional connection with the reader.`
  : '';

// ✅ additionalPrompt section — user ki extra instructions blog mein use hongi
const additionalPromptSection = d.additionalPrompt && d.additionalPrompt.trim() !== ''
  ? `
ADDITIONAL INSTRUCTIONS FROM USER (MUST FOLLOW):
${d.additionalPrompt}`
  : '';

const blogPrompt = `Write a complete, professional blog post with these exact specifications:
CORE DETAILS
Topic: ${d.topic}
Brand Name: ${d.brand}
Primary Keyword: ${d.primaryKeyword}
Secondary Keywords: ${d.secondaryKeywords}
LSI Keywords: ${d.lsiKeywords}
Opening Hook Question: ${d.hookQuestion}
Suggested Section Headings: ${d.suggestedH2s}
Meta Title: ${d.metaTitle}
Meta Description: ${d.metaDescription}
Target Word Count: ${d.wordCount} words
Language: ${d.language}
${audienceSection}
${brandStorySection}
BLOG FORMAT: ${d.blogFormat}
${d.formatInstruction}
WRITING STYLE: ${d.styleName}
${d.toneGuide}
STRUCTURE REQUIREMENTS
${d.structureGuide}
KEYWORD PLACEMENT RULES
${d.keywordStrategy}
${refStyleSection}
FORMATTING RULES
- Start with: # [Blog Title]
- Next line: Meta Title: ${d.metaTitle}
- Next line: Meta Description: ${d.metaDescription}
- ${tldrInstruction}
- Use ## for H2, ### for H3
- Use **bold** for important terms
- Use - for bullet points
- ${tableInstruction}
- ${faqInstruction}
- After FAQs: Tip: [practical tip]
- Final line: CTA: ${d.ctaText}
