=const blogMarkdown = $input.item.json.output || '';
const d            = $('Build prompt').item.json;
const productRefLink = d.productRefLink || $input.first().json.body?.['Product Reference Link (Optional)'] || '';

const date = new Date().toLocaleDateString('en-GB', { year:'numeric', month:'long', day:'numeric' });

const themes = {
  'Spiritual & Healing': { primary: '#6b4f8e', accent: '#c9a96e', bg: '#faf8fc', heading: '#3d2b5e', border: '#e8dff5' },
  'Luxury Editorial':    { primary: '#1a1a1a', accent: '#c9a655', bg: '#fdfcf8', heading: '#0d0d0d', border: '#e8e0cc' },
  'Technical Expert':    { primary: '#0052cc', accent: '#ff5630', bg: '#f8f9ff', heading: '#172b4d', border: '#dde4f0' },
  'Conversational Smart':{ primary: '#0a7569', accent: '#e85d04', bg: '#f8fffd', heading: '#064e3b', border: '#d1fae5' }
};

const t = themes[d.styleName] || themes['Technical Expert'];

// ══════════════════════════════════════════════════════════════
// STEP 1: <a> tags extract karke safe tokens mein rakh do
// ══════════════════════════════════════════════════════════════
const anchorStore = [];
let safe = blogMarkdown.replace(/<a[\s\S]*?<\/a>/gi, (match) => {
  const cleaned = match
    .replace(/>["'""](.+?)["'""]\s*<\/a>/gi, '>$1</a>')
    .replace(/>["'""](.+?)<\/a>/gi, '>$1</a>')
    .replace(/>(.+?)["'""]\s*<\/a>/gi, '>$1</a>');
  const i = anchorStore.length;
  anchorStore.push(cleaned);
  return `ANCHORTOKEN${i}ENDTOKEN`;
});

// ══════════════════════════════════════════════════════════════
// STEP 2: Baaki markdown clean karo
// ══════════════════════════════════════════════════════════════
safe = safe
  .replace(/(?<!(^|\n)#{1,6} ?)#(?![#\s])/gm, '')
  .replace(/"{3,}/g, '')
  .replace(/\u201C|\u201D|\u2018|\u2019/g, '')
  .replace(/\$(?!\d)/g, '')
  .replace(/(?<!\w)`(?!\w)/g, '')
  .replace(/&(?!amp;|lt;|gt;|nbsp;|quot;|#\d+;)/g, 'and');

// ══════════════════════════════════════════════════════════════
// STEP 3: Markdown → HTML
// ══════════════════════════════════════════════════════════════
function mdToHtml(md) {
  return md
    .replace(/^# (.+)$/gm,    '<h1>$1</h1>')
    .replace(/^## (.+)$/gm,   '<h2>$1</h2>')
    .replace(/^### (.+)$/gm,  '<h3>$1</h3>')
    .replace(/^#### (.+)$/gm, '<h4>$1</h4>')
    .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(.+?)\*\*/g,     '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,         '<em>$1</em>')
    .replace(/^(Q\d+\.\s.+)$/gm,  '<div class="faq-question">$1</div>')
    .replace(/^\|(.+)\|$/gm, row => {
      const cells = row.split('|').filter(c => c.trim());
      if (cells.every(c => /^[-:| ]+$/.test(c.trim()))) return '';
      return '<tr>' + cells.map((c, i) =>
        i === 0 && cells[0].trim().match(/^[A-Z]/)
          ? `<th>${c.trim()}</th>`
          : `<td>${c.trim()}</td>`
      ).join('') + '</tr>';
    })
    .replace(/(<tr>[\s\S]*?<\/tr>\n?)+/g, m => `<table>${m}</table>`)
    .replace(/^[-*] (.+)$/gm, '<li>$1</li>')
    .replace(/(<li>[\s\S]*?<\/li>\n?)+/g, m => `<ul>${m}</ul>`)
    .replace(/^Tip: (.+)$/gm,   '<div class="tip-box">&#128161; <strong>Tip:</strong> $1</div>')
    .replace(/^CTA: (.+)$/gm,   '<div class="cta-box"><a class="cta-btn">$1</a></div>')
    .replace(/^TL;DR: (.+)$/gm, '<div class="tldr-box"><strong>TL;DR:</strong> $1</div>')
    .replace(/^Meta Title:.+$/gm, '')
    .replace(/^Meta Description:.+$/gm, '')
    .replace(/\n{2,}/g, '</p>\n<p>')
    .replace(/<p>\s*(<[hut])/g, '$1')
    .replace(/(<\/h\d>|<\/ul>|<\/table>|<\/div>)\s*<\/p>/g, '$1');
}

// ══════════════════════════════════════════════════════════════
// STEP 4: FAQ processor
// ══════════════════════════════════════════════════════════════
function processFAQs(html) {
  const lines = html.split('\n');
  const out = [];
  let i = 0;
  while (i < lines.length) {
    if (lines[i].includes('class="faq-question"')) {
      let j = i + 1;
      while (j < lines.length && !lines[j].trim()) j++;
      if (j < lines.length) {
        const ans = lines[j].replace(/^<p>/, '').replace(/<\/p>$/, '');
        out.push(`<div class="faq-item">${lines[i]}<div class="faq-answer">${ans}</div></div>`);
        i = j + 1;
        continue;
      }
    }
    out.push(lines[i]);
    i++;
  }
  return out.join('\n');
}

// ══════════════════════════════════════════════════════════════
// STEP 5: Convert + anchors wapas restore karo
// ══════════════════════════════════════════════════════════════
let blogHtml = mdToHtml(safe);
blogHtml = processFAQs(blogHtml);

anchorStore.forEach((anchor, i) => {
  blogHtml = blogHtml.split(`ANCHORTOKEN${i}ENDTOKEN`).join(anchor);
});

// ══════════════════════════════════════════════════════════════
// STEP 6: productRefLink — comma-separated links, har link 1 baar
//         alag alag word pe lagega, already linked words skip
// ══════════════════════════════════════════════════════════════
const productRefLinks = productRefLink
  .split(',')
  .map(l => l.trim())
  .filter(l => l.length > 3);

if (productRefLinks.length > 0) {
  const linkCandidates = [
    d.primaryKeyword,
    d.brand,
    d.topic,
    'learn more', 'read more', 'find out',
    'discover', 'explore', 'check out', 'visit', 'see more'
  ].filter(w => w && w.trim().length > 3);

  const usedWords = new Set();

  for (const linkUrl of productRefLinks) {
    let linked = false;

    for (const word of linkCandidates) {
      if (linked) break;
      if (usedWords.has(word.toLowerCase())) continue;

      const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const regex = new RegExp(`(?<![">])(${escaped})(?![^<]*>|[^<>]*<\\/a>)`, 'i');

      blogHtml = blogHtml.replace(regex, (match) => {
        linked = true;
        usedWords.add(word.toLowerCase());
        return `<a href="${linkUrl}" target="_blank" rel="noopener" style="color:#e85d04;font-weight:bold;text-decoration:underline;">${match}</a>`;
      });
    }
  }
}

// ══════════════════════════════════════════════════════════════
// STEP 7: HTML document
// ══════════════════════════════════════════════════════════════
const refBadge = d.refLink && d.refLink.trim()
  ? `<div class="ref-badge">&#128279; <strong>Style Reference:</strong> <a href="${d.refLink}" target="_blank">${d.refLink}</a></div>`
  : '';

const htmlDoc = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${d.metaTitle}</title>
<meta name="description" content="${d.metaDescription}">
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Georgia', 'Cambria', serif; font-size: 11.5pt; line-height: 1.8; color: #1a1a1a; background: ${t.bg}; max-width: 820px; margin: 0 auto; padding: 50px 48px; }
