  .audience-box strong { color: ${t.primary}; }
  .ref-badge { background: #fffbea; border: 1px solid #f0d060; border-radius: 8px; padding: 10px 16px; margin-bottom: 28px; font-size: 9pt; font-family: 'Arial', sans-serif; color: #6b5000; }
