  h2 { font-size: 15pt; font-weight: bold; color: ${t.primary}; margin-top: 36px; margin-bottom: 12px; padding-left: 14px; border-left: 4px solid ${t.accent}; }
  h3 { font-size: 12.5pt; font-weight: bold; color: ${t.heading}; margin-top: 22px; margin-bottom: 8px; }
  h4 { font-size: 11.5pt; font-weight: bold; color: #444; margin-top: 16px; }
  p { margin: 10px 0; text-align: justify; }
  ul { padding-left: 26px; margin: 12px 0; }
  li { margin: 6px 0; }
