  ].filter(w => w && w.trim().length > 3);

  const usedWords = new Set();

  for (const linkUrl of productRefLinks) {
    let linked = false;

    // ✅ Protect: h1, tldr-box, tip-box, cta-box, faq-item, meta-box, audience-box, ref-badge, footer
    const protectedBlocks = [];
    let protectedHtml = blogHtml.replace(
