        linked = true;
        usedWords.add(word.toLowerCase());
        return `<a href="${linkUrl}" target="_blank" rel="noopener" style="color:#e85d04;font-weight:bold;text-decoration:underline;">${match}</a>`;
      });
    }

    // ✅ Protected blocks wapas restore karo
    protectedBlocks.forEach((block, idx) => {
      protectedHtml = protectedHtml.split(`__PROTECTED_BLOCK_${idx}__`).join(block);
    });

    blogHtml = protectedHtml;
